import java.io.*;

public class _1599_C {
    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        StringTokenizer line = new StringTokenizer(in.readLine());
        int n = Integer.parseInt(line.nextToken());
        double p = Double.parseDouble(line.nextToken());
        int total = chooseThree(n);
        findMin(n, p, total, 0, out);
        in.close();
        out.close();
    }
    static void findMin(int n, double p, int total, int i, PrintWriter out) {
        if (i > n) return;
        double prob = ((double) i * chooseTwo(n - i) / total / 2)
                    + ((double) chooseTwo(i) * (n - i) / total)
                    + ((double) chooseThree(i) / total);
        if (prob >= p) {
            out.println(i);
            return;
        }
        findMin(n, p, total, i + 1, out);
    }
    static int chooseTwo(int n) {
        if (n < 2) return 0;
        return n * (n - 1) / 2;
    }
    static int chooseThree(int n) {
        if (n < 3) return 0;
        return n * (n - 1) * (n - 2) / 6;
    }
}
